 the governance baseline is discoverable without redesigning the top-level docs.","tree":{"sha":"d30d1d092fbb3ac3e63d0971c41f97dafdf39f90","url":"https://api.github.com/repos/cjakabos/portfolio-web/git/trees/d30d1d092fbb3ac3e63d0971c41f97dafdf39f90"},"url":"https://api.github.com/repos/cjakabos/portfolio-web/git/commits/0ae2e8d0a5e5329a3fc27da5c30268f6c4c67f9b","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/54838312?v=4","events_url":"https://api.github.com/users/cjakabos/events{/privacy}","followers_url":"https://api.github.com/users/cjakabos/followers","following_url":"https://api.github.com/users/cjakabos/following{/other_user}","gists_url":"https://api.github.com/users/cjakabos/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/cjakabos","id":54838312,"login":"cjakabos","node_id":"MDQ6VXNlcjU0ODM4MzEy","organizations_url":"https://api.github.com/users/cjakabos/orgs","received_events_url":"https://api.github.com/users/cjakabos/received_events","repos_url":"https://api.github.com/users/cjakabos/repos","site_admin":false,"starred_url":"https://api.github.com/users/cjakabos/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/cjakabos/subscriptions","type":"User","url":"https://api.github.com/users/cjakabos","user_view_type":"public"},"html_url":"https://github.com/cjakabos/portfolio-web/commit/0ae2e8d0a5e5329a3fc27da5c30268f6c4c67f9b","node_id":"C_kwDOGVz28doAKDBhZTJlOGQwYTVlNTMyOWEzZmMyN2RhNWMzMDI2OGY2YzRjNjdmOWI","parents":[{"html_url":"https://github.com/cjakabos/portfolio-web/commit/09e1f22cd1fb2f17fcf3c30c8dc8b4fdee246003","sha":"09e1f22cd1fb2f17fcf3c30c8dc8b4fdee246003","url":"https://api.github.com/repos/cjakabos/portfolio-web/commits/09e1f22cd1fb2f17fcf3c30c8dc8b4fdee246003"}],"sha":"0ae2e8d0a5e5329a3fc27da5c30268f6c4c67f9b","url":"https://api.github.com/repos/cjakabos/portfolio-web/commits/0ae2e8d0