ure mode and validation command in TESTING.md","tree":{"sha":"de870cb02855b9c01ba65f9c0c76b290e2fea640","url":"https://api.github.com/repos/cjakabos/portfolio-web/git/trees/de870cb02855b9c01ba65f9c0c76b290e2fea640"},"url":"https://api.github.com/repos/cjakabos/portfolio-web/git/commits/307579e17e1077cfa94adb1719b965838d1df9ad","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/54838312?v=4","events_url":"https://api.github.com/users/cjakabos/events{/privacy}","followers_url":"https://api.github.com/users/cjakabos/followers","following_url":"https://api.github.com/users/cjakabos/following{/other_user}","gists_url":"https://api.github.com/users/cjakabos/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/cjakabos","id":54838312,"login":"cjakabos","node_id":"MDQ6VXNlcjU0ODM4MzEy","organizations_url":"https://api.github.com/users/cjakabos/orgs","received_events_url":"https://api.github.com/users/cjakabos/received_events","repos_url":"https://api.github.com/users/cjakabos/repos","site_admin":false,"starred_url":"https://api.github.com/users/cjakabos/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/cjakabos/subscriptions","type":"User","url":"https://api.github.com/users/cjakabos","user_view_type":"public"},"html_url":"https://github.com/cjakabos/portfolio-web/commit/307579e17e1077cfa94adb1719b965838d1df9ad","node_id":"C_kwDOGVz28doAKDMwNzU3OWUxN2UxMDc3Y2ZhOTRhZGIxNzE5Yjk2NTgzOGQxZGY5YWQ","parents":[{"html_url":"https://github.com/cjakabos/portfolio-web/commit/442526a46ef5e722dee8731881e6450adb59c9df","sha":"442526a46ef5e722dee8731881e6450adb59c9df","url":"https://api.github.com/repos/cjakabos/portfolio-web/commits/442526a46ef5e722dee8731881e6450adb59c9df"}],"sha":"307579e17e1077cfa94adb1719b965838d1df9ad","url":"https://api.github.com/repos/cjakabos/portfolio-web/commits/307579e17e1077cfa94adb1719b965838d1df9ad"},